/**
 * 基础布局样式（styles.css）的运行时字符串形态。
 * 由 scripts/gen-base-styles.mjs 从 src/styles.css 生成，请勿手改。
 *
 * 用途：让 ALL_CSS（all-css.ts）能在运行时聚合「布局 + 图标字体 + emoji」三份样式，
 * 供 SSR 消费者页面级一次性注入。改样式请改 src/styles.css，再跑 build（会自动重生成）。
 */

/** 基础布局样式（= src/styles.css 全文） */
export const BASE_STYLES_CSS: string =
  "/**\n * open-feishu-card 样式表。\n * 精简复刻飞书 Universal Card 外观，自包含（不依赖飞书 design token）。\n * 类名沿用飞书原版前缀 universal-card。\n *\n * 注意：header 高光纹理图通过 JS 内联 base64 注入到 .universal-card-header__bg\n * 的 background-image（见 renderCard 输出的内联 style），故此处不写 url()。\n */\n\n.universal-card-root {\n  /* 对齐飞书网页版 locale=zh 字体栈：西文优先 Helvetica Neue / Tahoma，\n   * 中文再回落到 PingFang SC / Microsoft Yahei。原先把 PingFang 放在西文字体前，\n   * Windows 上会用微软雅黑的拉丁字形，观感与真卡不一致。 */\n  font-family: -apple-system, BlinkMacSystemFont, \"Helvetica Neue\", Tahoma,\n    \"PingFang SC\", \"Microsoft YaHei\", Arial, \"Hiragino Sans GB\", sans-serif,\n    \"Apple Color Emoji\", \"Segoe UI Emoji\", \"Segoe UI Symbol\", \"Noto Color Emoji\";\n  font-size: 14px;\n  line-height: 1.6;\n  /* 飞书网页版在 html 上设了 font-smoothing: antialiased，卡片文字继承同一套平滑设置，\n   * macOS/Safari 上字重观感更细，与客户端一致。 */\n  -webkit-font-smoothing: antialiased;\n  -moz-osx-font-smoothing: grayscale;\n  color: #1f2329;\n  background-color: #fff;\n  position: relative;\n  border-radius: 8px;\n  /* 对齐飞书网页版 --line-border-card: var(--N300)；独立渲染器无消息气泡外包层，边框在 root */\n  border: 1px solid var(--N300);\n  overflow: hidden;\n  width: 100%;\n  max-width: 605px;\n  box-sizing: border-box;\n  /* 真机按「卡片容器宽度 > 320px」区分宽/窄屏按钮档位，这里用容器查询复刻 */\n  container-type: inline-size;\n  container-name: universal-card;\n  /* BEGIN PALETTE VARS (auto-generated from constants.ts PALETTE) */\n  /* 正文 color:var(--O400) 等依赖这些变量；与飞书 :root light 色阶对齐 */\n  --B50: #f0f4ff;\n  --B100: #e0e9ff;\n  --B200: #c2d4ff;\n  --B300: #94b4ff;\n  --B350: #7aa2ff;\n  --B400: #5083fb;\n  --B500: #336df4;\n  --B600: #1456f0;\n  --B700: #0442d2;\n  --B800: #002f9e;\n  --B900: #002270;\n  --C50: #fef0f8;\n  --C100: #fee2f2;\n  --C200: #f8c4e1;\n  --C300: #f598cc;\n  --C350: #eb78b8;\n  --C400: #df58a5;\n  --C500: #cc398c;\n  --C600: #b82879;\n  --C700: #9d1562;\n  --C800: #730744;\n  --C900: #550c35;\n  --G50: #e4fae1;\n  --G100: #d0f5ce;\n  --G200: #95e599;\n  --G300: #5cd168;\n  --G350: #35bd4b;\n  --G400: #32a645;\n  --G500: #258832;\n  --G600: #1a7526;\n  --G700: #0b6017;\n  --G800: #04430c;\n  --G900: #022c07;\n  --I50: #f2f3fd;\n  --I100: #e9eafb;\n  --I200: #cccff9;\n  --I300: #abb0f2;\n  --I350: #959bee;\n  --I400: #757df0;\n  --I500: #5b65f5;\n  --I600: #4752e6;\n  --I700: #333dcc;\n  --I800: #1e27a4;\n  --I900: #151b70;\n  --L50: #f2f8d3;\n  --L100: #e3f0a3;\n  --L200: #c8dd5f;\n  --L300: #a2c10b;\n  --L350: #91ad00;\n  --L400: #7b9207;\n  --L500: #6b7f06;\n  --L600: #5c6d08;\n  --L700: #4a5804;\n  --L800: #333d00;\n  --L900: #262e00;\n  --N00: #ffffff;\n  --N50: #f5f6f7;\n  --N100: #f2f3f5;\n  --N200: #eff0f1;\n  --N300: #dee0e3;\n  --N350: #d0d3d6;\n  --N400: #bbbfc4;\n  --N500: #8f959e;\n  --N600: #646a73;\n  --N650: #51565d;\n  --N700: #373c43;\n  --N800: #2b2f36;\n  --N900: #1f2329;\n  --N950: #0f1114;\n  --N1000: #000000;\n  --O50: #fff3e5;\n  --O100: #fee7cd;\n  --O200: #fec48b;\n  --O300: #ff9d4c;\n  --O350: #ff811a;\n  --O400: #ed6d0c;\n  --O500: #c25705;\n  --O600: #a44904;\n  --O700: #853a05;\n  --O800: #642b02;\n  --O900: #3b1a02;\n  --P50: #f5f0fe;\n  --P100: #efe6fe;\n  --P200: #dcc9fd;\n  --P300: #c8a9fc;\n  --P350: #b791fa;\n  --P400: #9f6ff1;\n  --P500: #8d55ed;\n  --P600: #7a35f0;\n  --P700: #611fd6;\n  --P800: #4811a6;\n  --P900: #2f0080;\n  --R50: #fef0f0;\n  --R100: #fee3e2;\n  --R200: #fdc6c4;\n  --R300: #f89e9b;\n  --R350: #ff7570;\n  --R400: #f54a45;\n  --R500: #e22e28;\n  --R600: #c02a26;\n  --R700: #a11c17;\n  --R800: #741915;\n  --R900: #590603;\n  --S50: #ffffdb;\n  --S100: #fffca3;\n  --S200: #fff67a;\n  --S300: #fff258;\n  --S350: #ffe928;\n  --S400: #e5ce00;\n  --S500: #c2a800;\n  --S600: #8f7c00;\n  --S700: #5c4f00;\n  --S800: #423700;\n  --S900: #2c2502;\n  --T50: #e2f8f5;\n  --T100: #c4f2ec;\n  --T200: #6fe8d8;\n  --T300: #33d6c0;\n  --T350: #2dbeab;\n  --T400: #10a893;\n  --T500: #0f8575;\n  --T600: #067062;\n  --T700: #045d51;\n  --T800: #03443b;\n  --T900: #02312a;\n  --V50: #fceefc;\n  --V100: #f9e2f9;\n  --V200: #f3c4f3;\n  --V300: #e59ce5;\n  --V350: #de81de;\n  --V400: #cf5ecf;\n  --V500: #bf3dbf;\n  --V600: #a630a6;\n  --V700: #872787;\n  --V800: #6a116a;\n  --V900: #520052;\n  --W50: #e7f8fe;\n  --W100: #caeffc;\n  --W200: #97dcfc;\n  --W300: #3ec3f7;\n  --W350: #25b0e7;\n  --W400: #1295ca;\n  --W500: #047fb0;\n  --W600: #076a94;\n  --W700: #0f587a;\n  --W800: #06415c;\n  --W900: #072b3d;\n  --Y50: #fbf4df;\n  --Y100: #faedc2;\n  --Y200: #fcdf7e;\n  --Y300: #fad355;\n  --Y350: #ffc60a;\n  --Y400: #d99904;\n  --Y500: #ad7a03;\n  --Y600: #865b03;\n  --Y700: #6f4a01;\n  --Y800: #573601;\n  --Y900: #382201;\n  /* END PALETTE VARS */\n  /* 真机 light：`--bg-float-overlay` 是实色 token（不是叠色）。\n     值取自客户端 light 主题 token 表（feishu-web-dump/debugger/19ecdc88…js 的\n     name→export→值映射）：bg-float-overlay / bg-body-overlay = rgb(245,246,247)。\n     早先按「真机截图」量到 (246,246,246) 改成了 rgba(30,30,30,.04)，但那份真机图是\n     JPEG（色度子采样把 #f5f6f7 压成中性 246），照抄反而让背景式面板比真机少一阶蓝。\n     #f5f6f7 与 grey-50 实为同值：grey → bg-float-overlay，grey-50 → N50。 */\n  --bg-float-overlay: #f5f6f7;\n  --bg-float-base: #f2f3f5;\n  --bg-filler: #eff0f1;\n  --bg-content-base: #f8f9fa;\n  /* 语义色 token（对齐客户端 light token 表）：容器描边/caption 文案/分割线/列表符号等\n     走语义名而不是直接挑色阶，避免「同一个 grey 在正文是 N600、作描边却是 N350」被抹平。 */\n  --line-border-component: var(--N350); /* 组件描边（collapsible_panel / interactive_container） */\n  --line-border-card: var(--N300);\n  /* 分割线/表格行线：真机是中性黑叠色，不是 N300 实色——之前用 #dee0e3 会让所有\n     横线比真机多 3~4 阶蓝（表格表头下方那条线最明显）。 */\n  --line-divider-default: rgba(31, 35, 41, 0.15);\n  --fill-hover: rgba(31, 35, 41, 0.08);\n  --text-caption: var(--N600);\n  --colorful-blue: var(--B500); /* markdown 列表符号 */\n  --bg-body: var(--N00);\n  --static-white: var(--N00);\n}\n.universal-card-root *,\n.universal-card-root *::before,\n.universal-card-root *::after { box-sizing: border-box; }\n\n/* ---- header ---- */\n.universal-card-header {\n  width: 100%;\n  overflow: hidden;\n}\n.universal-card-header__bg {\n  box-sizing: border-box;\n  width: 100%;\n  padding: 12px;\n  background-repeat: no-repeat;\n  background-position: 0 0;\n  /* 对齐飞书：max(100%, 605px) 140px，窄卡不把高光拉稀 */\n  background-size: max(100%, 605px) 140px;\n}\n/* default/disabled 模板真机不设背景色（bg_color 为空串），此时 header 不留底部内边距 */\n.universal-card-header__bg--no-template { padding-bottom: 0; }\n/* 内容行：左侧图标 + 右侧标题区（对齐网页版 header__content = row） */\n.universal-card-header__content {\n  width: 100%;\n  display: flex;\n  flex-direction: row;\n  align-items: flex-start;\n}\n.universal-card-header__icon {\n  display: flex;\n  height: 24px;\n  align-items: center;\n  margin-right: 8px;\n  flex-shrink: 0;\n  color: inherit;\n}\n.universal-card-header__text {\n  flex: 1;\n  max-width: 100%;\n  line-height: 24px;\n  overflow: hidden;\n  min-width: 0;\n}\n/* 标题行：标题 + 右侧标签同排 */\n.universal-card-header__text-title-wrapper,\n.universal-card-header__title-row {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n}\n.universal-card-header__tags {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  line-height: 1;\n  max-width: 100%;\n}\n.universal-card-header__text-title {\n  overflow: hidden;\n  margin-right: 4px;\n  font-size: 16px;\n  font-weight: 600;\n  line-height: 24px;\n  word-break: break-word;\n}\n/* 副标题：与标题同色，仅字重更轻（对齐真机 font-weight:400，无 opacity） */\n.universal-card-header__text-subtitle {\n  margin-top: 2px;\n  font-size: 14px;\n  font-weight: 400;\n  line-height: 22px;\n  overflow: hidden;\n  display: -webkit-box;\n  -webkit-box-orient: vertical;\n  -webkit-line-clamp: 1;\n  word-break: break-word;\n}\n\n/* ---- body ---- */\n.universal-card-body {\n  padding: 12px;\n  display: flex;\n  flex-direction: column;\n  row-gap: 12px;\n  column-gap: 12px;\n  align-items: flex-start;\n}\n/* 交互控件不参与「子元素撑满」：按钮的宽度由真机规则决定（见 .universal-card-button--auto），\n   若被这条 blanket 规则拉到 100%，窄屏/宽屏分档就失效了。 */\n.universal-card-body > *:not(.universal-card-button) { width: 100%; box-sizing: border-box; }\n\n/* ---- markdown 段落 ---- */\n/* 对齐网页版：line-height 默认 1.6；具体字号/行高由组件内联 style 按 text_size 给出 */\n.universal-card-markdown {\n  display: flex;\n  width: 100%;\n  box-sizing: border-box;\n  font-size: 14px;\n  line-height: 1.6;\n  color: #1f2329;\n  word-break: break-word;\n  vertical-align: middle;\n}\n/* 前缀图标（markdown.icon）：与首行文字垂直居中，右侧留 4px。\n   容器是 flex row，图标作为首个 flex 子项参与排布。 */\n.universal-card-markdown__icon {\n  display: inline-flex; align-items: center; justify-content: center;\n  flex-shrink: 0; margin-right: 4px;\n  height: 1.6em;\n}\n.universal-card-markdown__children {\n  flex: 1;\n  min-width: 0;\n  overflow: hidden;\n  white-space: pre-wrap;\n}\n\n/* ---- hr 分割线 ---- */\n/* 真机 block_hr / md_hr：backgroundColorToken = line-divider-default\n   （客户端 light = rgba(31,35,41,.15) → 叠白 (221,222,223)，比 #dee0e3 中性）。 */\n.universal-card-hr {\n  width: 100%;\n  height: 1px;\n  background-color: var(--line-divider-default, #dee0e3);\n  border: none;\n  margin: 8px 0;\n}\n\n.universal-card-collapse-divider {\n  width: 100%;\n  height: 1px;\n  background-color: var(--line-divider-default, #dee0e3);\n  border: none;\n  margin: 8px 0;\n}\n\n.universal-card-avatar {\n  display: inline-flex;\n  align-items: center;\n  vertical-align: middle;\n}\n\n.universal-card-avatar__img {\n  border-radius: 50%;\n  object-fit: cover;\n  display: block;\n  background: #eff0f1;\n}\n\n.universal-card-fallback-text {\n  color: #646a73;\n  font-size: 14px;\n  line-height: 22px;\n}\n\n/* ---- div ---- */\n.universal-card-div > * + * { margin-top: 8px; }\n/* div 带前置图标：icon 在左、文本在右排成一行（复刻网页版 .universal-card-div 布局） */\n.universal-card-div--with-icon {\n  display: flex; flex-wrap: nowrap; align-items: flex-start; line-height: 1.6;\n}\n.universal-card-div--with-icon > * + * { margin-top: 0; }\n.universal-card-div__icon_wrapper {\n  margin-right: 8px; flex-shrink: 0; height: 1.6em;\n  display: flex; align-items: center; overflow: hidden;\n}\n.universal-card-div__content { flex: 1; min-width: 0; }\n\n/* ---- 布局：column_set / column ---- */\n.universal-card-column-set { display: flex; flex-wrap: nowrap; }\n.universal-card-column { box-sizing: border-box; overflow-wrap: anywhere; }\n/* 真机：有背景才挂 --bg。column_set 额外 4px 内边距；column 只圆角、不加默认 padding。 */\n.universal-card-column-set--bg { padding: 4px; border-radius: 6px; }\n.universal-card-column--bg { border-radius: 6px; }\n/* 列内纵向间距唯一来源是 column 组件输出的 flex row-gap（默认 8px，可被 vertical_spacing 覆盖）。\n   这里不再给相邻子元素设 margin-top——否则与 row-gap 叠加，间距翻倍。 */\n\n/* ---- 图片 ---- */\n/* 真机图片外层是 .universal-card-element-shell.universal-card-image（width:100%），\n   内部再放标题 + 图片容器；标题在图片上方，靠 margin-bottom 拉开 8px。 */\n.universal-card-image { width: 100%; box-sizing: border-box; }\n.universal-card-image__title { margin-bottom: 8px; }\n\n/* 真机网页版 .universal-card-image__host{border-radius:0}：图片默认直角，\n   圆角只由 DSL/RAW 的 corner_radius 内联给出（见 img 组件）。\n   之前这里写死 4px，导致没写 corner_radius 的图在渲染器里四角被圆掉，与真机不符。 */\n/* 真机 .universal-card-image__wrapper{position:relative;display:flex;flex-direction:row;\n   align-items:center;flex:0 1 auto;width:100%;max-width:100%;overflow:hidden} */\n.universal-card-image__wrapper {\n  position: relative; display: flex; flex-direction: row; align-items: center;\n  flex: 0 1 auto; width: 100%; max-width: 100%; overflow: hidden;\n}\n/* 真机 .universal-card-image__host{object-fit:cover;width:100%;border-radius:0;font-size:0;position:static} */\n.universal-card-image__host {\n  width: 100%; max-width: 100%; height: auto; object-fit: cover;\n  border-radius: 0; font-size: 0; position: static;\n}\n.universal-card-image__placeholder {\n  display: inline-flex; align-items: center; justify-content: center;\n  min-width: 80px; min-height: 48px; padding: 8px 12px;\n  color: #8f959e; background: #f5f6f7; border: 1px dashed #dee0e3; border-radius: 4px;\n  font-size: 12px;\n}\n\n/* ---- img_combination 多图混排（比例逆向自网页版 .universal-card-img-combination） ---- */\n.universal-card-img-combination { display: flex; width: 100%; justify-content: space-between; }\n.universal-card-img-combination__item { min-width: 0; overflow: hidden; }\n.universal-card-img-combination__item > .universal-card-image__host { display: block; width: 100%; height: 100%; object-fit: cover; }\n.universal-card-img-combination__item > .universal-card-image__placeholder { width: 100%; height: 100%; }\n/* double：左窄(32.4%, 24:33) + 右宽(67.6%, 49.33:33) */\n.universal-card-img-combination--double .universal-card-img-combination__item:nth-child(odd) {\n  width: 32.4%; aspect-ratio: 24 / 33;\n}\n.universal-card-img-combination--double .universal-card-img-combination__item:nth-child(2n) {\n  width: calc(67.6% - 4px); aspect-ratio: 49.33 / 33;\n}\n/* triple：左大图(66.5%, 1:1) + 右列两张小图 */\n.universal-card-img-combination--triple .universal-card-img-combination__left {\n  width: 66.5%; aspect-ratio: 1; margin-right: 1%;\n}\n.universal-card-img-combination--triple .universal-card-img-combination__right {\n  width: 33%; display: flex; flex-direction: column; justify-content: space-between;\n}\n.universal-card-img-combination--triple .universal-card-img-combination__right .universal-card-img-combination__item {\n  width: 100%; aspect-ratio: 1;\n}\n.universal-card-img-combination--triple .universal-card-img-combination__right .universal-card-img-combination__item:first-child {\n  margin-bottom: 1.5%;\n}\n/* bisect / trisect：等宽方格换行 */\n.universal-card-img-combination--bisect { flex-wrap: wrap; gap: 4px; }\n.universal-card-img-combination--bisect .universal-card-img-combination__item {\n  width: calc(50% - 2px); aspect-ratio: 1;\n}\n.universal-card-img-combination--trisect { flex-wrap: wrap; justify-content: flex-start; gap: 4px; }\n.universal-card-img-combination--trisect .universal-card-img-combination__item {\n  width: calc(33.33% - 2.67px); aspect-ratio: 1;\n}\n\n/* ---- select_img 多图选择（对齐网页版 .universal-card-select-img） ---- */\n.universal-card-select-img {\n  width: 100%; max-width: 100%; display: grid; grid-gap: 4px; box-sizing: border-box;\n}\n.universal-card-select-img--stretch { grid-template-columns: 1fr; }\n.universal-card-select-img--bisect { grid-template-columns: 1fr 1fr; }\n.universal-card-select-img--trisect { grid-template-columns: 1fr 1fr 1fr; }\n.universal-card-select-img__item-wrapper { position: relative; border-radius: 6px; }\n.universal-card-select-img__item-wrapper::after {\n  content: \" \"; position: absolute; inset: 0; box-sizing: border-box;\n  border: 1px solid var(--N300); border-radius: 6px; pointer-events: none; z-index: 1;\n}\n.universal-card-select-img__item-wrapper--selected::after { border: 2px solid var(--B500); }\n.universal-card-select-img__item {\n  position: relative; overflow: hidden; box-sizing: border-box; border-radius: 6px;\n  cursor: pointer; width: 100%;\n}\n.universal-card-select-img__item--disabled { cursor: not-allowed; }\n.universal-card-select-img__item--disabled::after {\n  content: \" \"; position: absolute; inset: 0; z-index: 1;\n  background-color: rgba(255, 255, 255, .5);\n}\n.universal-card-select-img__item > .universal-card-image__host {\n  display: block; width: 100%; height: 100%; object-fit: cover;\n}\n.universal-card-select-img__item > .universal-card-image__placeholder {\n  width: 100%; height: 100%;\n}\n/* 表单内复选/单选标记（真机仅 in-form 显示；表单外用选中描边表达状态） */\n.universal-card-select-img__checkbox {\n  position: absolute; top: 0; right: 0; z-index: 2; padding: 5px 8px; cursor: pointer;\n}\n.universal-card-select-img__checkbox--disabled { cursor: not-allowed; }\n.universal-card-select-img__checkbox-box {\n  display: inline-flex; align-items: center; justify-content: center;\n  width: 16px; height: 16px; box-sizing: border-box; border-radius: 50%;\n  background-color: rgba(0, 0, 0, .15); border: 1px solid #eff0f1;\n  box-shadow: 0 0 2px rgba(0, 0, 0, .1);\n}\n.universal-card-select-img__checkbox-box--square { border-radius: 4px; }\n.universal-card-select-img__checkbox-box--checked {\n  background-color: var(--B500); border-color: var(--B500);\n}\n.universal-card-select-img__checkbox-box--checked::after {\n  content: \"\"; width: 3.5px; height: 7px;\n  border: solid #fff; border-width: 0 2px 2px 0;\n  transform: rotate(45deg) translateY(-1px);\n}\n\n/* ---- 按钮 ---- */\n/* 飞书按钮文本是纯文本、单行：min-height 容纳偶发换行，文字超长省略号收尾。\n   样式全集逆向自网页版 ud__button：三大族——outlined（描边）/ text（纯文字）/ filled（实心），\n   每族再分 default / primary / danger 色，另加 laser 渐变。默认（未加变体类）= outlined-default。 */\n.universal-card-button {\n  display: inline-flex; align-items: center; justify-content: center;\n  gap: 4px;\n  min-height: 28px; padding: 4px 12px;\n  font-family: inherit;\n  font-size: 14px; line-height: 22px; border-radius: 6px;\n  border: 1px solid transparent; background: transparent; color: #1f2329;\n  cursor: pointer; text-decoration: none; box-sizing: border-box;\n  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;\n  transition: background-color .1s, border-color .1s, color .1s;\n}\n/* 按钮前置图标：继承按钮文字色（currentColor），高度对齐行高 */\n.universal-card-button__icon {\n  display: inline-flex; align-items: center; justify-content: center;\n  flex-shrink: 0; height: 1.2em; color: inherit;\n}\n.universal-card-button__icon .universal-card-icon { color: inherit; }\n/* 宽度：对齐真机 ud__button 的 isWide 分档（真机按「卡片容器宽度 > 320px」判定）：\n   宽屏 → 自适应内容宽（--auto）；窄屏（≤320px）→ 撑满整行（下方 @container 规则覆盖）。\n   text 族与 width:\"fill\" 恒定撑满（--block）。\n   align-self:flex-start —— 父级（body/form/column）默认 align-items:stretch，\n   只写 width:auto 仍会被拉伸，必须同时阻止拉伸。 */\n.universal-card-button { min-width: 58px; align-self: flex-start; }\n.universal-card-button--block { width: 100%; min-width: unset; }\n.universal-card-button--auto { width: auto; }\n\n/* —— outlined 描边族 —— */\n/* default：灰描边 + 白底 + 深字（未加变体类的裸 .universal-card-button 已是白底深字，\n   这里补上默认灰边与 default 变体一致） */\n.universal-card-button,\n.universal-card-button--default {\n  border-color: #dee0e3; background: #fff; color: #1f2329;\n}\n.universal-card-button--default:not(.universal-card-button--static):hover { background: #f5f6f7; }\n/* primary：蓝描边 + 蓝字 + 白底 */\n.universal-card-button--primary {\n  border-color: #1456f0; background: #fff; color: #1456f0;\n}\n.universal-card-button--primary:not(.universal-card-button--static):hover { background: #f0f4ff; }\n/* danger：红描边 + 红字 + 白底 */\n.universal-card-button--danger {\n  border-color: #f54a45; background: #fff; color: #f54a45;\n}\n.universal-card-button--danger:not(.universal-card-button--static):hover { background: #fef0f0; }\n\n/* —— text 纯文字族（无边框/无底色；撑满时文字靠左，对齐真机） —— */\n.universal-card-button--text,\n.universal-card-button--primary_text,\n.universal-card-button--danger_text {\n  border-color: transparent; background: transparent; padding: 4px 8px;\n  justify-content: flex-start;\n  /* 真机 text 族按钮不设最小宽度 */\n  min-width: unset;\n}\n.universal-card-button--text { color: #1f2329; }\n.universal-card-button--primary_text { color: #1456f0; }\n.universal-card-button--danger_text { color: #f54a45; }\n.universal-card-button--text:not(.universal-card-button--static):hover { background: #f5f6f7; }\n.universal-card-button--primary_text:not(.universal-card-button--static):hover { background: #f0f4ff; }\n.universal-card-button--danger_text:not(.universal-card-button--static):hover { background: #fef0f0; }\n\n/* —— filled 实心族（有底色 + 白字） —— */\n.universal-card-button--primary_filled {\n  border-color: #1456f0; background: #1456f0; color: #fff;\n}\n.universal-card-button--primary_filled:not(.universal-card-button--static):hover { background: #0442d2; border-color: #0442d2; }\n.universal-card-button--danger_filled {\n  border-color: #f54a45; background: #f54a45; color: #fff;\n}\n.universal-card-button--danger_filled:not(.universal-card-button--static):hover { background: #e22e28; border-color: #e22e28; }\n/* laser：飞书「激光」渐变实心按钮（蓝→紫渐变 + 白字） */\n.universal-card-button--laser {\n  border-color: transparent; color: #fff;\n  background: linear-gradient(97deg, #4e83fd 0%, #7a35f0 100%);\n}\n.universal-card-button--laser:not(.universal-card-button--static):hover { filter: brightness(1.05); }\n\n.universal-card-button--disabled,\n.universal-card-button:disabled { opacity: .5; cursor: not-allowed; pointer-events: none; }\n/* 非跳转按钮：保留外观，但不可点（默认光标、无 hover、不响应点击） */\n.universal-card-button--static { cursor: default; pointer-events: none; }\n\n/* ---- overflow 折叠按钮组 ---- */\n/* 真机是一个「…」图标按钮，点击弹出选项菜单。静态预览只画触发器（--static 不可点）。 */\n.universal-card-overflow { display: inline-flex; position: relative; vertical-align: middle; }\n.universal-card-overflow--static { display: inline-flex; }\n.universal-card-overflow__summary {\n  list-style: none; cursor: pointer; display: inline-flex;\n  /* 真机折叠按钮的最小宽度是 32px（普通按钮是 58px） */\n  min-width: 32px;\n}\n/* 去掉 <summary> 的浏览器默认三角标记 */\n.universal-card-overflow__summary::-webkit-details-marker { display: none; }\n.universal-card-overflow__summary::marker { content: ''; }\n/* 菜单：默认隐藏，<details open> 时浮在触发器下方 */\n.universal-card-overflow__menu {\n  display: none;\n  position: absolute; top: calc(100% + 4px); left: 0; z-index: 20;\n  min-width: 120px; padding: 4px 0;\n  background: #fff; border-radius: 6px;\n  box-shadow: 0 4px 12px rgba(31, 35, 41, 0.15), 0 0 1px rgba(31, 35, 41, 0.2);\n}\n.universal-card-overflow[open] > .universal-card-overflow__menu { display: block; }\n.universal-card-overflow__item {\n  display: block; padding: 6px 12px;\n  font-size: 14px; line-height: 22px; color: #1f2329;\n  text-decoration: none; white-space: nowrap; cursor: pointer;\n}\n.universal-card-overflow__item:hover { background: #f5f6f7; }\n\n/* ---- 表单（预览：仅透传，无表单语义） ---- */\n/* row-gap 12px：对齐真机 schema 2.0 表单容器 */\n.universal-card-form { display: flex; flex-direction: column; row-gap: 12px; }\n.universal-card-form > *:not(.universal-card-button) { width: 100%; }\n/* input / select：静态预览是只读框；interactive 去掉 --static，成为可输入控件 */\n.universal-card-input,\n.universal-card-input--static {\n  min-height: 32px; padding: 6px 12px; box-sizing: border-box;\n  font-family: inherit; font-size: 14px; line-height: 20px;\n  background: #fff; border: 1px solid #dee0e3; border-radius: 6px;\n  color: #1f2329; width: 100%;\n  /* 真机 input 默认 max-width:282px（width:\"fill\" 时由内联样式放开） */\n  max-width: 282px;\n}\n/* select type:\"text\"：真机是无边框、内容自适应宽的下拉 */\n.universal-card-input--text {\n  border-color: transparent; background: transparent;\n  min-height: 26px; padding: 1px 7px; width: auto;\n}\n.universal-card-input--static {\n  color: #8f959e; background: #f5f6f7;\n  cursor: default; pointer-events: none;\n}\n\n/* ---- checker 勾选器（对齐网页版 universal-card-checker） ---- */\n.universal-card-checker {\n  display: flex; box-sizing: border-box; overflow: hidden; align-items: flex-start;\n  color: inherit;\n}\n.universal-card-checker--hover.universal-card-checker:hover {\n  background-color: rgba(31, 35, 41, 0.05); cursor: pointer;\n}\n.universal-card-checker--disabled { opacity: .5; cursor: not-allowed; pointer-events: none; }\n.universal-card-checker__checkbox-container {\n  display: inline-flex; align-items: center; margin-right: 8px; flex-shrink: 0;\n  height: calc(var(--universal-card-checker-line-height, 22px));\n  position: relative; cursor: pointer;\n}\n/* 原生 checkbox 藏起，用自定义方框画外观；点击由外层 label / 本 label 承接 */\n.universal-card-checker__input {\n  position: absolute; opacity: 0; width: 0; height: 0; margin: 0; padding: 0;\n}\n.universal-card-checker__box {\n  width: 16px; height: 16px; box-sizing: border-box;\n  border: 1px solid #8f959e; border-radius: 4px; background: #fff;\n  display: inline-flex; align-items: center; justify-content: center;\n  flex-shrink: 0; transition: background-color .1s, border-color .1s;\n}\n.universal-card-checker__input:checked + .universal-card-checker__box {\n  background: #1456f0; border-color: #1456f0;\n}\n.universal-card-checker__input:checked + .universal-card-checker__box::after {\n  content: \"\"; width: 3.5px; height: 7px;\n  border: solid #fff; border-width: 0 2px 2px 0;\n  transform: rotate(45deg) translateY(-0.5px);\n}\n.universal-card-checker__content {\n  /* 真机：content 是 flex，唯一子项是 .universal-card-text（行内排版）。\n   * 不要把 text_tag / plain_text 直接做成 flex 子项——行首空格会被吃掉，\n   * tag 与后续文字贴死（真机靠 break-spaces + 行内流保留 content 里的空格）。 */\n  display: flex; flex: 1; min-width: 35px;\n  line-height: calc(var(--universal-card-checker-line-height, 22px));\n  word-break: break-word;\n}\n/* 真机 .universal-card-text：保留连续空格（text_tag 后常见两个空格） */\n.universal-card-text {\n  word-break: break-word;\n  white-space: break-spaces;\n}\n/* textStyle.attributes → BEM 修饰类（对齐真机 bold/italic/through） */\n.universal-card-text--bold { font-weight: 600; }\n.universal-card-text--italic { font-style: italic; }\n.universal-card-text--through { text-decoration: line-through; }\n/* 勾选态：删除线 / 透明度由 :has(:checked) 驱动，本地切换无需 JS */\n.universal-card-checker--strike:has(.universal-card-checker__input:checked) .universal-card-checker__content {\n  text-decoration-line: line-through;\n  text-decoration-color: inherit;\n}\n.universal-card-checker:has(.universal-card-checker__input:checked) .universal-card-checker__content {\n  opacity: var(--checker-checked-opacity, 1);\n}\n.universal-card-checker__content--right { justify-content: right; }\n.universal-card-checker__content--center { justify-content: center; }\n.universal-card-checker__buttons {\n  display: flex; margin-left: 16px; column-gap: 10px; max-width: 150px; flex-shrink: 0;\n  align-items: center;\n}\n.universal-card-checker__buttons--auto-hide { opacity: 0; }\n.universal-card-checker:hover .universal-card-checker__buttons--auto-hide { opacity: 1; }\n.universal-card-checker__button { display: inline-flex; align-items: center; }\n\n\n/* ---- interactive_container 可点击交互容器 ---- */\n/* 真机无默认圆角；圆角只由 DSL/RAW corner_radius 内联输出（见 resolveCornerRadius）。 */\n.universal-card-interactive-container {\n  display: flex; flex-direction: column; box-sizing: border-box;\n  padding: 0; text-decoration: none; color: inherit;\n  row-gap: 4px;\n  transition: background-color .1s;\n}\n/* 真机：cursor:pointer 与 hover 底只在 __action 层；纯展示容器（无 actions/url）保持默认箭头 */\n.universal-card-interactive-container--action { cursor: pointer; }\n.universal-card-interactive-container--action:not(.universal-card-interactive-container--disabled):hover {\n  background-color: rgba(31, 35, 41, 0.05);\n}\n.universal-card-interactive-container--bordered { border: 1px solid var(--line-border-component); }\n/* disabled：去掉手型指针与 hover 灰底，外观退回普通块 */\n.universal-card-interactive-container--disabled {\n  cursor: default; transition: none;\n}\n\n/* ---- collapsible_panel 折叠面板（原生 <details>/<summary>，纯 CSS 可点） ---- */\n/* 外层 <details> 容器：border/background/radius 由内联 style 给（来自 border/background_color）。 */\n.universal-card-collapsible-panel {\n  box-sizing: border-box; overflow: hidden;\n}\n/* header（<summary>）：可点击整行；去掉浏览器默认三角标记。\n   真机 color:var(--text-caption) → N600；标题/箭头继承此色。\n   默认 title flex:1 把箭头推到右侧（icon_position=right）；\n   icon_position=left 时靠 DOM 顺序在左。\n   内边距只在 --fat 时由 CSS 给 4px 8px，纯无样式面板不加内边距；\n   --fat 的判定 = 面板有描边 / 面板底色 / 标题区底色（组件里 isFat）；\n   header.padding 显式给了就由内联 style 覆盖。\n   来源：网页版 .universal-card-collapsible-panel__header（无 padding 声明）\n   + .universal-card-collapsible-panel--fat ....__header{padding:4px 8px}。 */\n.universal-card-collapsible-panel__header {\n  display: flex; align-items: center; gap: 8px;\n  padding: 0;\n  cursor: pointer; box-sizing: border-box;\n  list-style: none; user-select: none;\n  color: var(--N600);\n}\n.universal-card-collapsible-panel--fat .universal-card-collapsible-panel__header {\n  padding: 4px 8px;\n}\n.universal-card-collapsible-panel__header::-webkit-details-marker { display: none; }\n.universal-card-collapsible-panel__header::marker { content: ''; }\n/* header.vertical_align：center（默认）/ top / bottom */\n.universal-card-collapsible-panel__header--valign-top { align-items: flex-start; }\n.universal-card-collapsible-panel__header--valign-bottom { align-items: flex-end; }\n/* header.width：fill（默认，撑满整行）/ auto（自适应内容宽）/\n   auto_when_fold（折叠自适应、展开撑满——真机语义） */\n.universal-card-collapsible-panel__header--w-auto,\n.universal-card-collapsible-panel__header--w-auto-when-fold {\n  width: max-content; max-width: 100%;\n}\n.universal-card-collapsible-panel[open] > .universal-card-collapsible-panel__header--w-auto-when-fold {\n  width: 100%;\n}\n.universal-card-collapsible-panel__title {\n  flex: 1; min-width: 0; font-size: 14px; line-height: 22px;\n  word-break: break-word;\n}\n/* title ↔ expanded_title：有 expanded_title 时，折叠展示 title、展开展示 expanded_title\n   （真机语义）。纯 CSS 由 details[open] 驱动，不学要 JS 同步。 */\n.universal-card-collapsible-panel__title-text { display: block; }\n.universal-card-collapsible-panel__title--has-expanded\n  .universal-card-collapsible-panel__title-text--expanded { display: none; }\n.universal-card-collapsible-panel[open]\n  .universal-card-collapsible-panel__title--has-expanded .universal-card-collapsible-panel__title-text { display: none; }\n.universal-card-collapsible-panel[open]\n  .universal-card-collapsible-panel__title--has-expanded\n  .universal-card-collapsible-panel__title-text--expanded { display: block; }\n/* follow_text：箭头紧贴文字（真机 __header-content--icon-follow），不拉满整行 */\n.universal-card-collapsible-panel__header--icon-follow {\n  gap: 4px;\n}\n/* icon_position=left：图标与 header-content 是同级子项，真机 header 的 column-gap 是 4px\n   （right 时图标在 header-content 里，间距是 8px） */\n.universal-card-collapsible-panel__header--icon-left {\n  gap: 4px;\n}\n.universal-card-collapsible-panel__header--icon-follow .universal-card-collapsible-panel__title {\n  flex: 0 1 auto;\n  width: auto;\n}\n/* 箭头图标包裹：收起态角度 0；展开态（details[open]）旋转到 --panel-icon-angle（内联给出，默认 -180deg）。\n   由用户点击 <summary> 切换 [open]，箭头方向随之自动更新，无需 JS。颜色继承 header caption。 */\n.universal-card-collapsible-panel__icon {\n  flex-shrink: 0; display: inline-flex; align-items: center; justify-content: center;\n  transition: transform .1s linear; transform: rotate(0deg);\n}\n.universal-card-collapsible-panel[open] .universal-card-collapsible-panel__icon {\n  transform: rotate(var(--panel-icon-angle, -180deg));\n}\n/* 内容区：展开时显示（折叠态由 <details> 交给浏览器隐藏）。\n   对齐真机：内容区是 flex 容器（element-shell__container），默认纵向 + 8px 行列间距；\n   内边距基础只有 padding-top:8px，--fat 面板改成四边 8px。\n   （之前写死 0 12px 12px：标题行左边距比真机多 4px，正文顶部少 8px，\n   多个子元素之间也缺了真机的 8px 间距。） */\n.universal-card-collapsible-panel__content {\n  box-sizing: border-box; padding: 8px 0 0;\n  display: flex; flex-direction: column;\n  row-gap: 8px; column-gap: 8px;\n}\n.universal-card-collapsible-panel--fat .universal-card-collapsible-panel__content {\n  padding: 8px;\n}\n\n/* ---- 人员 person_v1 / person_list（对齐网页版 universal-card-person*）---- */\n.universal-card-person {\n  display: inline-flex; align-items: center; width: auto; max-width: 100%;\n}\n/* 有头像：网页版就是 vertical-align:bottom。middle 按拉丁 x-height 居中，\n * 中文行里整盒（头像 18 + 姓名 22）会视觉偏下。\n * 仅姓名：跟正文基线对齐，不要 bottom/middle。 */\n.universal-card-markdown .universal-card-person--avatar,\n.universal-card-person--avatar {\n  vertical-align: bottom;\n}\n.universal-card-markdown .universal-card-person:not(.universal-card-person--avatar) {\n  vertical-align: baseline;\n  align-items: baseline;\n}\n.universal-card-markdown .universal-card-person:not(.universal-card-person--avatar) .universal-card-person__content,\n.universal-card-markdown .universal-card-person:not(.universal-card-person--avatar) .universal-card-person__name {\n  align-items: baseline;\n}\n.universal-card-person__content {\n  display: flex; align-items: center; max-width: 100%; cursor: default;\n}\n/* 真机 --udtoken-tag-neutral-bg-normal = rgba(N900-raw, .1) = rgba(31,35,41,.1) */\n.universal-card-person__content--capsule.universal-card-person__content--name {\n  background: rgba(31, 35, 41, 0.1); border-radius: 99px;\n}\n.universal-card-person__avatar-wrapper {\n  display: flex; flex-shrink: 0;\n}\n.universal-card-person__internal-avatar,\n.universal-card-person-list__avatar,\n.universal-card-person-list__unknown-avatar {\n  flex-shrink: 0; border-radius: 50%; object-fit: cover;\n  display: inline-flex; align-items: center; justify-content: center;\n  overflow: hidden; vertical-align: middle;\n}\n.universal-card-person__avatar--placeholder {\n  background-color: #bbbfc4; color: #fff; font-weight: 500;\n  line-height: 1; text-transform: uppercase; user-select: none;\n}\n.universal-card-person__name {\n  display: inline-flex; align-items: center; min-width: 0;\n  color: #1f2329; max-width: 100%;\n}\n/* 真机 --line-1 是 block + nowrap，不是 -webkit-box clamp；\n * clamp 会破坏 inline-flex 基线，姓名在正文里看起来靠下。 */\n.universal-card-person__name .universal-card-text--line-1 {\n  display: block; white-space: nowrap;\n  overflow: hidden; text-overflow: ellipsis;\n}\n.universal-card-person .universal-card-text { line-height: inherit; }\n\n.universal-card-person-list {\n  display: flex; width: 100%; position: relative; align-items: flex-start;\n  justify-content: flex-start;\n}\n.universal-card-person-list--table {\n  flex-wrap: wrap; gap: 4px 8px; width: auto;\n}\n.universal-card-person-list__icon {\n  margin-right: 8px; flex-shrink: 0; overflow: hidden;\n  display: flex; align-items: center; height: 1.6em;\n}\n.universal-card-person-list__content {\n  overflow: hidden; min-width: 0; flex: 1;\n}\n.universal-card-person-list__content--lines {\n  display: -webkit-box; -webkit-box-orient: vertical; overflow: hidden;\n}\n.universal-card-person-list__content--combine {\n  display: flex; flex-wrap: wrap; column-gap: 12px; row-gap: 8px;\n}\n.universal-card-person-list__avatar-name {\n  display: inline-flex; overflow: hidden; text-overflow: ellipsis;\n  white-space: nowrap; align-items: center; max-width: 100%;\n}\n.universal-card-person-list__avatar-name .universal-card-person-list__avatar,\n.universal-card-person-list__avatar-name .universal-card-person-list__unknown-avatar {\n  margin-right: 4px; flex-shrink: 0;\n}\n.universal-card-person-list__reaction-user {\n  align-items: center; display: inline-flex; overflow: hidden;\n  text-overflow: ellipsis; white-space: nowrap; max-width: 100%;\n  vertical-align: middle;\n}\n.universal-card-person-list__reaction-user--blue { color: #1456f0; }\n.universal-card-person-list__reaction-user--disabled { cursor: default; }\n.universal-card-person-list__reaction-user__name {\n  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;\n  vertical-align: middle; display: inline-block; max-width: 100%;\n}\n.universal-card-person-list__reaction-user__comma {\n  color: #8f959e; white-space: pre; vertical-align: middle;\n}\n/* 葫芦串：叠放头像，重叠处用 SVG mask 挖月牙（对齐 ud__avatar-hollow-out，不用白描边） */\n.universal-card-person-list__avatar-group {\n  display: inline-flex; align-items: center; white-space: nowrap;\n}\n.universal-card-person-list__avatar-group-item {\n  display: inline-flex; border-radius: 50%; overflow: hidden;\n  position: relative; flex-shrink: 0;\n}\n.universal-card-person-list__avatar-group-item .universal-card-person-list__avatar,\n.universal-card-person-list__avatar-group-item .universal-card-person-list__unknown-avatar {\n  display: block; width: 100%; height: 100%;\n}\n\n/* ---- @人 / 链接 ---- */\n.universal-card-markdown-at { word-break: break-word; }\n.universal-card-markdown-link { color: #1456f0; text-decoration: none; }\n.universal-card-markdown-link:hover { text-decoration: underline; }\n\n/* ---- text_tag 彩色标签 ---- */\n.universal-card-text-tag { vertical-align: middle; margin: 0 2px; white-space: nowrap; }\n\n/* ---- markdown: heading / blockquote / list / code ---- */\n.universal-card-markdown-heading { word-break: break-word; }\n.universal-card-blockquote {\n  padding-left: 10px; position: relative; color: #646a73;\n}\n.universal-card-blockquote::before {\n  content: \" \"; position: absolute; left: 0; top: 0; height: 100%; width: 2px;\n  background-color: var(--line-divider-default, #dee0e3);\n}\n/* 列表：结构对齐网页版——每个 item 一个 <ul>/<ol> + 一个 <li data-marker>，\n   缩进落在 ul/ol 的 margin-left（内联 24*level），项目符号用 li::before 画。\n   网页版符号是「右对齐到距正文 20px」的绝对定位盒（width:0 + margin:auto 20px auto -20px），\n   不是行内 marker + gap：那样符号会紧贴文字，且字宽算进了缩进。 */\n.universal-card-markdown-list { text-align: left; }\n.universal-card-markdown-list__ul,\n.universal-card-markdown-list__ol { padding: 0; margin: 0; }\n.universal-card-markdown-list__ul > li,\n.universal-card-markdown-list__ol > li {\n  position: relative; list-style-position: outside; list-style-type: none;\n}\n.universal-card-markdown-list__ul > li { padding-left: 22px; }\n.universal-card-markdown-list__ul > li::before,\n.universal-card-markdown-list__ol > li::before {\n  display: inline-block; color: var(--colorful-blue); content: \"\";\n  box-sizing: border-box; border-radius: 2px; padding: 0 2px;\n  min-width: 18px; position: absolute;\n}\n/* 无序：• ◦ ▪ 按层级轮替（data-marker = level % 3）；字号固定 14px，不跟正文缩放 */\n.universal-card-markdown-list__ul > li::before {\n  content: \"\\2022\"; font-size: 14px; font-family: \"PingFang SC\", \"PingFangSC-Regular\", sans-serif;\n  width: 0; min-width: auto; top: 0; bottom: 0;\n  margin: auto 20px auto -20px; text-align: right; line-height: inherit;\n}\n.universal-card-markdown-list__ul > li[data-marker=\"1\"]::before { content: \"\\25E6\"; font-weight: 700; }\n.universal-card-markdown-list__ul > li[data-marker=\"2\"]::before { content: \"\\25AA\"; }\n/* 有序：序号跟着正文基线排（inline-flex 首个子项），与真机一致 */\n.universal-card-markdown-list__ol > li { display: inline-flex; }\n.universal-card-markdown-list__ol > li::before {\n  position: relative; margin-right: 2px; line-height: inherit;\n  content: attr(data-marker); text-align: left; min-width: 1em; white-space: nowrap;\n  font-family: \"Helvetica Neue\", Consolas, monospace; flex-shrink: 0;\n}\n.universal-card-markdown-list__li-content { display: inline-block; vertical-align: top; }\n.universal-card-code-span {\n  /* 真机 .universal-card-code-span：border 1px line-divider-default、bg --bg-base(#f2f3f5)、padding 0 2px */\n  border-radius: 4px;\n  border: 1px solid var(--line-divider-default, #dee0e3);\n  padding: 0 2px;\n  background-color: var(--bg-float-base, #f2f3f5);\n  font-family: Menlo, Consolas, monospace; font-size: 13px;\n}\n.universal-card-markdown-code-block {\n  /* 真机：border 1px line-border-card、bg --bg-body-overlay(#f5f6f7) */\n  text-align: left; padding: 12px; min-width: 210px; margin: 4px 0;\n  font-size: 13px; font-weight: 400; line-height: 1.5;\n  background-color: var(--bg-body-overlay, #f5f6f7);\n  border: 1px solid var(--line-border-card, #dee0e3);\n  border-radius: 6px; overflow-x: auto;\n  font-family: Menlo, Consolas, monospace; white-space: pre;\n}\n.universal-card-emoji { display: inline; }\n/* emoji 雪碧图：<i> 的 background-image/size/position/width 由 emoji.css（larkw-emoji__img--emoji-*）提供；\n   这里只管行内对齐（vertical-align 让表情与文字基线大致对齐）。 */\n.universal-card-emoji__img { display: inline-block; vertical-align: -0.15em; }\n\n/* 图标（standard_icon / ud_icon）：glyph 由图标字体 :before 画出。\n   字体 @font-face 与每图标 content 规则随 JS 注入（浏览器端 renderCard 自动注入，\n   Node/SSR 端引入 open-feishu-card/icon-font.css）。这里只管布局对齐。 */\n.universal-card-icon {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  vertical-align: -0.125em;\n}\n\n/* ---- video 视频 ---- */\n/* 对齐飞书 .universal-card-video：有 src 时原生 <video controls>；无 src 时封面 + 播放钮。 */\n.universal-card-video {\n  position: relative;\n  display: block;\n  width: 100%;\n  min-width: 96px;\n  min-height: 54px;\n  aspect-ratio: 16 / 9;\n  background-color: rgba(0, 0, 0, 0.8);\n  overflow: hidden;\n  cursor: default;\n  border-radius: 4px;\n  object-fit: contain;\n  box-sizing: border-box;\n}\n.universal-card-video__cover {\n  width: 100%;\n  height: 100%;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n}\n.universal-card-video__host-image {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  display: block;\n}\n.universal-card-video__default-cover {\n  width: 100%;\n  height: 100%;\n  background: linear-gradient(135deg, #2b2f36 0%, #1f2329 100%);\n}\n.universal-card-video__play-btn {\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  width: 40px;\n  height: 40px;\n  margin: -20px 0 0 -20px;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  color: #fff;\n  font-size: 18px;\n  border: 1px solid #fff;\n  border-radius: 50%;\n  background: rgba(0, 0, 0, 0.4);\n  box-sizing: border-box;\n  pointer-events: none;\n}\n.universal-card-video__duration {\n  position: absolute;\n  bottom: 6px;\n  right: 6px;\n  padding: 0 4px;\n  height: 16px;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  font-size: 10px;\n  color: #fff;\n  background-color: rgba(0, 0, 0, 0.55);\n  border: 1px solid rgba(255, 255, 255, 0.1);\n  border-radius: 4px;\n  user-select: none;\n  box-sizing: border-box;\n}\n\n/* ---- audio 音频 ---- */\n/* 对齐飞书 .universal-card-audio__*：自定义播放条，非原生 controls。\n * 顶层 audio = 块级圆角条；markdown_audio = --inline 胶囊（padding/圆角/扁平图标不同）。 */\n.universal-card-audio__wrapper {\n  position: relative;\n  align-self: flex-start;\n  background: var(--universal-card-audio-bg, #f5f6f7);\n  cursor: pointer;\n  transition: background-color 0.3s ease;\n  border: 1px solid var(--line-border-card, #dee0e3);\n  border-radius: 8px;\n  padding: 12px;\n  box-sizing: border-box;\n  max-width: 100%;\n}\n.universal-card-audio__wrapper--disabled {\n  background: var(--universal-card-audio-disabled-bg, #eff0f1);\n  cursor: default;\n}\n.universal-card-audio__wrapper:hover:not(.universal-card-audio__wrapper--disabled) {\n  background: var(--universal-card-audio-hover-bg, var(--universal-card-audio-bg, #eff0f1));\n}\n/* 禁用蒙层：真机用白色半透明遮罩盖住内容（含内边距），而非整体 opacity */\n.universal-card-audio__mask {\n  position: absolute;\n  top: calc(0px - var(--universal-card-audio-border-width, 0px));\n  right: calc(0px - var(--universal-card-audio-border-width, 0px));\n  bottom: calc(0px - var(--universal-card-audio-border-width, 0px));\n  left: calc(0px - var(--universal-card-audio-border-width, 0px));\n  z-index: 10;\n  background-color: rgba(255, 255, 255, 0.5);\n  border-radius: inherit;\n}\n/* markdown 内嵌：行内容胶囊（真机 --inline） */\n.universal-card-audio__wrapper--inline {\n  display: inline-flex;\n  margin: 0 3px;\n  padding: 4px 7px;\n  border-radius: 30px;\n}\n.universal-card-audio__native {\n  display: none;\n}\n.universal-card-audio__component {\n  max-width: 100%;\n  position: relative;\n}\n.universal-card-audio__control {\n  width: 100%;\n  display: flex;\n  align-items: center;\n  column-gap: 12px;\n  box-sizing: border-box;\n  user-select: none;\n  color: #8f959e;\n}\n.universal-card-audio__wrapper--inline .universal-card-audio__control {\n  position: relative;\n  column-gap: 0;\n  padding-left: calc(var(--universal-card-audio-icon-size, 0) + 2px);\n  height: var(--universal-card-audio-icon-size, 16px);\n}\n.universal-card-audio__ctrl {\n  flex-grow: 0;\n  flex-shrink: 0;\n  width: var(--universal-card-audio-icon-size, 20px);\n  height: var(--universal-card-audio-icon-size, 20px);\n  cursor: pointer;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  color: var(--universal-card-audio-fill-color, #1f2329);\n}\n.universal-card-audio__wrapper--inline .universal-card-audio__ctrl {\n  position: absolute;\n  left: 0;\n  top: 50%;\n  transform: translateY(-50%);\n}\n.universal-card-audio__ctrl-icon {\n  font-size: var(--universal-card-audio-icon-size, 20px);\n  line-height: 1;\n  display: inline-flex;\n  color: inherit;\n  position: relative;\n}\n.universal-card-audio__wrapper--inline .universal-card-audio__ctrl-icon {\n  left: 8%;\n  transform: scale(0.85);\n}\n.universal-card-audio__icon {\n  display: inline-flex;\n  color: inherit;\n}\n.universal-card-audio__icon--pause { display: none; }\n/* 播放中：隐藏播放钮、显示暂停钮（由 hydrate 给 wrapper 加 --playing） */\n.universal-card-audio__wrapper--playing .universal-card-audio__icon--play { display: none; }\n.universal-card-audio__wrapper--playing .universal-card-audio__icon--pause { display: inline-flex; }\n.universal-card-audio__ctrl-icon svg,\n.universal-card-audio__icon svg {\n  display: block;\n  width: 1em;\n  height: 1em;\n}\n.universal-card-audio__slider {\n  position: relative;\n  flex-grow: 1;\n  min-width: 32px;\n  height: 6px;\n  cursor: pointer;\n}\n.universal-card-audio__slider-bg {\n  position: absolute;\n  left: 0;\n  top: 50%;\n  height: 1px;\n  background-color: rgba(31, 35, 41, 0.3);\n  margin-top: -1px;\n  width: 100%;\n}\n.universal-card-audio__process {\n  background-color: var(--universal-card-audio-fill-color, #1f2329);\n  width: 0;\n  height: 100%;\n  left: 0;\n}\n.universal-card-audio__slider-strip {\n  position: absolute;\n  width: 16px;\n  height: 16px;\n  margin-top: -8px;\n  margin-left: -8px;\n  border-radius: 8px;\n  box-sizing: border-box;\n  background-color: #fff;\n  top: 50%;\n  left: 0;\n  cursor: pointer;\n  box-shadow: 0 0 8px 0 rgba(31, 35, 41, 0.16);\n  transform: scale(0.5);\n  transition: transform 0.3s ease;\n}\n.universal-card-audio__wrapper:hover:not(.universal-card-audio__wrapper--disabled) .universal-card-audio__slider-strip {\n  transform: scale(1);\n}\n.universal-card-audio__time {\n  color: var(--universal-card-audio-fill-color, #1f2329);\n  position: relative;\n  width: 38px;\n  flex-grow: 0;\n  flex-shrink: 0;\n  font-size: var(--universal-card-audio-time-font-size, 12px);\n  font-weight: 500;\n  text-align: center;\n}\n/* 时长 ≥1h：HH:MM:SS 需要更宽（对齐真机 --long / --both / both+long） */\n.universal-card-audio__time--long { width: 52px; }\n.universal-card-audio__time--both { width: 84px; }\n.universal-card-audio__time--both.universal-card-audio__time--long { width: 116px; }\n.universal-card-audio__wrapper--inline .universal-card-audio__time {\n  width: calc(var(--universal-card-audio-time-font-size, 12px) * 3);\n}\n.universal-card-audio__wrapper--inline .universal-card-audio__time--long {\n  width: calc(var(--universal-card-audio-time-font-size, 12px) * 4.8);\n}\n\n/* ---- chart 图表 ---- */\n/* 挂载容器：aspect-ratio / height 由内联 style 给（来自 aspect_ratio）。\n   VChart 水合后会往 __vchart 里塞 <canvas>；水合前显示 loading 占位。 */\n.universal-card-chart {\n  position: relative;\n  width: 100%;\n  box-sizing: border-box;\n  overflow: hidden;\n}\n.universal-card-chart__vchart {\n  position: relative;\n  width: 100%;\n  height: 100%;\n  display: block;\n}\n.universal-card-chart__vchart canvas { display: block; }\n.universal-card-chart__loading,\n.universal-card-chart__placeholder {\n  display: flex; align-items: center; justify-content: center;\n  width: 100%; height: 100%;\n  color: #8f959e; font-size: 12px;\n  background: #f5f6f7; border: 1px dashed #dee0e3; border-radius: 4px;\n  box-sizing: border-box;\n}\n\n/* ---- table 表格 ---- */\n/* 表头背景：header_style.background_style=grey → 真机 token udtoken-table-bg-head\n   （客户端 light = #f2f3f5 = N100），不是 N50 —— 之前写 #f5f6f7 偏浅。 */\n.universal-card-table {\n  width: 100%;\n  /* 表格横向滚动靠内层 __scroll，外层不要被内容（列宽总和）顶宽：\n     否则在 flex 父级里会变成 min-content = 列宽总和，把整张卡撑出屏幕。 */\n  min-width: 0;\n  box-sizing: border-box;\n  border: 1px solid var(--line-border-card, #dee0e3);\n  border-radius: 6px;\n  overflow: hidden;\n}\n.universal-card-table__scroll { width: 100%; overflow-x: auto; }\n/* 列宽固定（真机每列都有算出来的像素宽，等价于 table-layout:fixed）：\n   文本超长时在单元格内截断，而不是把列撑宽 / 让行变高。\n   自适应列由组件按 128px 下限算出 min-width，空间不够就横向滚动。 */\n.universal-card-table__table {\n  width: 100%;\n  border-collapse: collapse;\n  table-layout: fixed;\n  font-size: 14px;\n  color: #1f2329;\n}\n/* 行线/列线都走 line-divider-default（中性黑叠色 rgba(31,35,41,.15)）。\n   列线是半透明的，会叠在单元格底色上：表头列线叠 #f2f3f5 → (211,211,214)≈#d4d4d7，\n   表体列线叠白 → (222,222,223)——与真机取色一致。\n   之前列线写死 --bg-filler(#eff0f1)：实色浅灰，比真机浅两档且偏蓝。\n   padding 同样是 0：真机 td 不设内边距，内边距在内容层（表体 0 8px、表头 6px 8px），\n   这样 td height 才是真机的 32/54/88，而不是被 8px 上下内边距顶高。 */\n.universal-card-table__th,\n.universal-card-table__td {\n  padding: 0;\n  border-bottom: 1px solid var(--line-divider-default, #dee0e3);\n  border-right: 1px solid var(--line-divider-default, #dee0e3);\n  vertical-align: middle;\n  box-sizing: border-box;\n}\n.universal-card-table__th:last-child,\n.universal-card-table__td:last-child { border-right: none; }\n.universal-card-table__tbody tr:last-child .universal-card-table__td { border-bottom: none; }\n/* 默认表头：text-title（N900）。header_style.text_color 由内联 style 覆盖。\n   真机表头单元格是 PlainText：padding 6px 8px（row-title），默认 1 行、超出省略号。\n   这里不能写死 white-space:nowrap——header_style.lines>1 时要能换行做多行截断。 */\n.universal-card-table__th {\n  padding: 6px 8px;\n  font-size: 14px;\n  line-height: 22px;\n  color: #1f2329;\n}\n.universal-card-table__th-text--bold { font-weight: 600; }\n/* 表体单元格：flex 是为了 options/persons 这类行内块内容也能跟随对齐；\n   max-height 由组件按行高内联给出（= 真机 row-item-wrapper 的 max-height）。 */\n.universal-card-table__cell {\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  padding: 0 8px;\n  box-sizing: border-box;\n  min-width: 0;\n  overflow: hidden;\n  word-break: break-word;\n}\n/* 自动行高（row_height=auto）：内容最多到 max-height，超出滚动（真机 --auto） */\n.universal-card-table__cell--auto { overflow: auto; padding: 4.8px 8px; }\n/* 单元格/表头文本截断（对齐真机 .universal-card-text--line-1 / --line-N）：\n   - 1 行：nowrap + ellipsis，中英文都不换行，末尾「…」；\n   - N 行：-webkit-line-clamp，第 N 行末尾「…」。\n   之前只有 word-break:break-word，长文本全部换行把行撑高，与真机完全不同。 */\n.universal-card-table__line-1 {\n  display: block;\n  min-width: 0;\n  max-width: 100%;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n.universal-card-table__lines {\n  display: -webkit-box;\n  -webkit-box-orient: vertical;\n  min-width: 0;\n  max-width: 100%;\n  overflow: hidden;\n  word-break: break-word;\n}\n.universal-card-table__tags { display: inline; }\n/* 单行行高下人员羹袋不换行（真机 PersonList lines=1），否则换行后会被 max-height 从中间剪开 */\n.universal-card-table__line-1 .universal-card-person-list { flex-wrap: nowrap; }\n\n/* 暗色主题下的表格/图表占位（分割线/描边 token 同步换成 dark 值） */\n.universal-card-root.theme-dark .universal-card-table { border-color: #2e2e30; }\n.universal-card-root.theme-dark .universal-card-table__th,\n.universal-card-root.theme-dark .universal-card-table__td { color: #d6d6d6; }\n.universal-card-root.theme-dark .universal-card-table__th { color: #ebebeb; }\n.universal-card-root.theme-dark .universal-card-chart__loading,\n.universal-card-root.theme-dark .universal-card-chart__placeholder {\n  background: #232323; border-color: #2e2e30; color: #8a8a8a;\n}\n\n/* ---- 暗色主题（可选）：给 .universal-card-root 加 .theme-dark 即可 ----\n   暗色高光图同样由 JS 注入；如需纯 CSS 暗色，可自行覆盖 background-image。 */\n.universal-card-root.theme-dark {\n  color: #ebebeb;\n  background-color: #1a1a1a;\n  border-color: #2e2e30;\n  /* 暗色 token：bg-float-overlay → N200 #373737；分割线反向叠白 15% */\n  --bg-float-overlay: #373737;\n  --line-divider-default: rgba(207, 207, 207, 0.15);\n}\n.universal-card-root.theme-dark .universal-card-markdown { color: #d6d6d6; }\n.universal-card-root.theme-dark .universal-card-hr { background-color: #2e2e30; }\n\n/* ---- Toast 宿主（对齐客户端 .ud__toast.ud__notice：顶部下拉、深色胶囊） ---- */\n.universal-card-toast-host {\n  position: fixed;\n  top: 32px; /* 客户端组件配置 toast:{top:32} */\n  left: 50%;\n  transform: translateX(-50%);\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  z-index: 300;\n  pointer-events: none;\n}\n.universal-card-toast {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  max-width: 600px; /* 客户端 .ud__toast max-width:600px */\n  padding: 9px 16px; /* 客户端 .ud__notice--filled padding:9px 0 9px 16px */\n  border-radius: 6px; /* 客户端 .ud__notice border-radius:6px */\n  background: rgba(31, 35, 41, 0.92); /* N900 深色半透明，白字 */\n  color: #fff;\n  font-size: 14px;\n  line-height: 1.5;\n  box-shadow: var(--shadow-s4-down, 0 4px 16px rgba(0, 0, 0, 0.16));\n  margin-bottom: 16px; /* 客户端 .ud__toast margin-bottom:16px */\n  animation: universal-card-toast-in 0.3s cubic-bezier(0.2, 0, 0, 1);\n}\n/* outlined 浅色变体：对齐客户端 .ud__notice--outlined.ud__notice-{type}\n   浅底 + 同色描边 + 深色文字（真机第二张：浅橙底橙边 warning） */\n.universal-card-toast--outlined {\n  background: #fff;\n  color: #1f2329;\n}\n.universal-card-toast--outlined.universal-card-toast--warning {\n  background: #fff7e6;\n  border: 1px solid #ff9d4c;\n}\n.universal-card-toast--outlined.universal-card-toast--error {\n  background: #fef1f1;\n  border: 1px solid #f54a45;\n}\n.universal-card-toast--outlined.universal-card-toast--info {\n  background: #e8f0ff;\n  border: 1px solid #3370ff;\n}\n.universal-card-toast--outlined.universal-card-toast--success {\n  background: #f0fbef;\n  border: 1px solid #34c724;\n}\n.universal-card-toast--leave {\n  animation: universal-card-toast-out 0.3s cubic-bezier(0.2, 0, 0, 1) forwards;\n}\n.universal-card-toast__icon {\n  flex: none;\n  display: inline-flex;\n}\n.universal-card-toast__text {\n  display: -webkit-box;\n  -webkit-box-orient: vertical;\n  overflow: hidden;\n  word-break: break-word;\n}\n@keyframes universal-card-toast-in {\n  from { opacity: 0; transform: translateY(-100%); }\n  to { opacity: 1; transform: translateY(0); }\n}\n@keyframes universal-card-toast-out {\n  from { opacity: 1; transform: translateY(0); }\n  to { opacity: 0; transform: translateY(-100%); margin-bottom: 0; }\n}\n\n/* ---- 窄屏分档（真机 isWide：卡片容器宽度 > 320px 为宽屏） ----\n   真机规则：default/primary/primary_filled/danger/danger_filled/laser 按钮在窄屏撑满整行，\n   宽屏则自适应内容宽。@container 不增加选择器权重，靠源码顺序在 --auto 规则之后覆盖。 */\n@container universal-card (max-width: 320px) {\n  .universal-card-button--auto { width: 100%; }\n}\n\n/* ---- column_set 的 flex_mode 只在窄屏生效（对齐客户端 isWide） ----\n   客户端 ni()：`isWide && (flexMode = None)`，宽屏（容器 > 320px）下 flex_mode 整个作废，\n   列的 width / weighted 照常；窄屏才走 ei()：\n     stretch → width:100%（配合 wrap 每列独占一行）\n     bisect  → calc(50% - gap/2)\n     trisect → calc(33.33% - 2gap/3)\n     flow    → width:auto（px / weighted 全部忽略，按内容宽排列）\n   这些覆盖必须用 !important：列宽是内联 style 输出的。\n   gap 由 column_set 内联的 --universal-card-column-gap 提供。 */\n@container universal-card (max-width: 320px) {\n  .universal-card-column-set--flow,\n  .universal-card-column-set--stretch,\n  .universal-card-column-set--bisect,\n  .universal-card-column-set--trisect { flex-wrap: wrap; }\n\n  .universal-card-column-set--stretch > .universal-card-column {\n    width: 100% !important;\n    flex-grow: 0 !important;\n    flex-basis: auto !important;\n    flex-shrink: 1 !important;\n  }\n  .universal-card-column-set--bisect > .universal-card-column {\n    width: calc(50% - var(--universal-card-column-gap, 8px) / 2) !important;\n    flex-grow: 0 !important;\n    flex-basis: auto !important;\n  }\n  .universal-card-column-set--trisect > .universal-card-column {\n    width: calc(33.33% - var(--universal-card-column-gap, 8px) * 2 / 3) !important;\n    flex-grow: 0 !important;\n    flex-basis: auto !important;\n  }\n  .universal-card-column-set--flow > .universal-card-column {\n    width: auto !important;\n    flex-grow: 0 !important;\n    flex-basis: auto !important;\n  }\n}\n";
